const sharedFullMapPathPlanners = new Map<string, FullMapPathPlanner>();

interface SharedMatchWorld {
    readonly staticObjects: SharedStaticObjectPool;
    readonly staticSpatialGrid: SpatialGrid<GameObject>;
    indexedStaticRevision: number;
    users: number;
}

const sharedMatchWorlds = new Map<string, SharedMatchWorld>();

const acquireSharedMatchWorld = (matchId: string): SharedMatchWorld => {
    let world = sharedMatchWorlds.get(matchId);
    if (!world) {
        world = {
            staticObjects: new SharedStaticObjectPool(),
            staticSpatialGrid: new SpatialGrid<GameObject>(
                64,
                (object) => object.data.pos as Vec2 | undefined,
            ),
            indexedStaticRevision: -1,
            users: 0,
        };
        sharedMatchWorlds.set(matchId, world);
    }
    world.users++;
    return world;
};

/** Shared static index plus one small per-bot dynamic visibility index. */
class MatchSpatialView {
    private readonly dynamicGrid = new SpatialGrid<GameObject>(
        64,
        (object) => object.data.pos as Vec2 | undefined,
    );

    constructor(private readonly world: SharedMatchWorld) {}

    rebuild(entities: Iterable<GameObject>): void {
        if (this.world.indexedStaticRevision !== this.world.staticObjects.revision) {
            this.world.staticSpatialGrid.rebuild(
                Object.values(this.world.staticObjects.idToObj),
            );
            this.world.indexedStaticRevision = this.world.staticObjects.revision;
        }
        const dynamic: GameObject[] = [];
        for (const entity of entities) {
            if (
                entity.__type !== ObjectType.Obstacle
                && entity.__type !== ObjectType.Building
                && entity.__type !== ObjectType.Structure
            ) dynamic.push(entity);
        }
        this.dynamicGrid.rebuild(dynamic);
    }

    queryRadius(center: Vec2, radius: number): GameObject[] {
        return [
            ...this.world.staticSpatialGrid.queryRadius(center, radius),
            ...this.dynamicGrid.queryRadius(center, radius),
        ];
    }

    clear(): void {
        this.dynamicGrid.clear();
    }
}

const releaseSharedMatchWorld = (matchId: string, world: SharedMatchWorld): void => {
    world.users = Math.max(0, world.users - 1);
    if (world.users === 0 && sharedMatchWorlds.get(matchId) === world) {
        sharedMatchWorlds.delete(matchId);
    }
};

